public sealed class Order
{
    private readonly List<object> _events = new();

    public int Id { get; private set; }
    public string CustomerName { get; private set; } = "";
    public OrderStatus Status { get; private set; } = OrderStatus.Pending;
    public string? Carrier { get; private set; }
    public DateTime? ShippedAt { get; private set; }

    public IReadOnlyList<object> Events => _events.AsReadOnly();
    public void ClearEvents() => _events.Clear();

    private Order() { }

    public Order(string customerName)
    {
        if (string.IsNullOrWhiteSpace(customerName))
            throw new ArgumentException("customer name required", nameof(customerName));
        CustomerName = customerName;
        Status = OrderStatus.Pending;
    }

    public void Ship(string carrier, DateTime when)
    {
        if (Status != OrderStatus.Pending)
            throw new InvalidOperationException($"cannot ship order in state {Status}");
        if (string.IsNullOrWhiteSpace(carrier))
            throw new ArgumentException("carrier required", nameof(carrier));
        Status = OrderStatus.Shipped;
        Carrier = carrier;
        ShippedAt = when;
        _events.Add(new OrderShipped(Id, carrier, when));
    }

    public void Cancel()
    {
        if (Status == OrderStatus.Shipped)
            throw new InvalidOperationException("cannot cancel shipped order");
        Status = OrderStatus.Cancelled;
        _events.Add(new OrderCancelled(Id));
    }
}

public enum OrderStatus { Pending, Shipped, Cancelled }
public sealed record OrderShipped(int OrderId, string Carrier, DateTime ShippedAt);
public sealed record OrderCancelled(int OrderId);

public sealed record ShipOrderCommand(int OrderId, string Carrier)
    : IRequest<ShipOrderResponse>;

public sealed record ShipOrderResponse(int OrderId, string Status, DateTime ShippedAt);

public sealed class ShipOrderValidator : AbstractValidator<ShipOrderCommand>
{
    public ShipOrderValidator()
    {
        RuleFor(x => x.OrderId).GreaterThan(0);
        RuleFor(x => x.Carrier).NotEmpty().MaximumLength(50);
    }
}

public sealed class ShipOrderHandler
    : IRequestHandler<ShipOrderCommand, ShipOrderResponse>
{
    private readonly IOrderRepository _orders;
    private readonly IUnitOfWork _uow;
    private readonly TimeProvider _time;

    public ShipOrderHandler(IOrderRepository orders, IUnitOfWork uow, TimeProvider time)
    {
        _orders = orders;
        _uow = uow;
        _time = time;
    }

    public async Task<ShipOrderResponse> Handle(
        ShipOrderCommand req, CancellationToken ct)
    {
        var order = await _orders.GetAsync(req.OrderId, ct)
            ?? throw new NotFoundException($"order {req.OrderId} not found");
        var when = _time.GetUtcNow().UtcDateTime;
        order.Ship(req.Carrier, when);
        await _uow.SaveChangesAsync(ct);
        return new ShipOrderResponse(order.Id, nameof(OrderStatus.Shipped), when);
    }
}

// Application/DependencyInjection.cs — the one place behaviours are ordered.
public static IServiceCollection AddApplication(this IServiceCollection services)
{
    services.AddValidatorsFromAssembly(typeof(DependencyInjection).Assembly);
    // Order is load-bearing: a validator registered after the handler never runs.
    services.AddTransient(typeof(IPipelineBehavior<,>), typeof(LoggingBehavior<,>));
    services.AddTransient(typeof(IPipelineBehavior<,>), typeof(ValidationBehavior<,>));
    services.AddTransient(typeof(IPipelineBehavior<,>), typeof(AuthorizationBehavior<,>));
    services.AddTransient(typeof(IPipelineBehavior<,>), typeof(UnitOfWorkBehavior<,>));
    services.AddTransient(typeof(IPipelineBehavior<,>), typeof(CachingBehavior<,>));
    return services;
}

// Api/Controllers/OrdersController.cs — dispatch and nothing else.
[HttpPost("{id:int}/ship")]
public async Task<ActionResult<ShipOrderResponse>> Ship(
    int id, ShipOrderRequest body, CancellationToken ct) =>
    Ok(await _mediator.Send(new ShipOrderCommand(id, body.Carrier), ct));

